        ///. Safety classification: No injury or damage to health is possible (IEC 62304 Class A).
        /// </summary>
        /// <returns>List of Patients</returns>
        public List<Patient> GetAllPatient()
        {
            List<Patient> patientlist = new List<Patient>();
            using (var context = new DataAccessContainer())
            {
                IQueryable<Patient> patients = from p in context.Patients
                                               orderby p.FirstName
                                               select p;
                patientlist = patients.ToList();
                foreach (Patient p in patientlist)
                {
                    p.FirstName = DecryptedValue(p.FirstNameEncrypted, 1);
                    p.LastName = DecryptedValue(p.LastNameEncrypted, 1);
                    p.DateOfBirth = DateTime.Parse(DecryptedValue(p.DateOfBirthEncrypted, 2));
                    p.Weight = float.Parse(DecryptedValue(p.WeightEncrypted, 3));
                    p.Height = float.Parse(DecryptedValue(p.HeightEncrypted, 3));
                    p.Gender = short.Parse(DecryptedValue(p.GenderEncrypted, 4));
                }
            }

            return patientlist;
        }

