        /// <returns>List of procedures</returns>
        public List<Procedure> GetAllProcedures()
        {
            List<Procedure> procedureList = null;


            using (var context = new DataAccessContainer())
            {
                IQueryable<Procedure> procedures = from procedure in context.Procedures.Include("Ablations")
                                                   where procedure.Archived == false
                                                   orderby procedure.ProcedureStartDateTime descending, procedure.Id ascending
                                                   select procedure;

                // GeT all Procedure instead than 20 
                procedureList = procedures.ToList();
            }
            return procedureList;
        }



        /// <summary>
        /// Function that retrieves all the procedures that contains ablation in the database.
        /// The result list is sorted by the most recent first
        ///. Safety classification: No injury or damage to health is possible (IEC 62304 Class A).
        /// </summary>
        /// <returns>List of procedures</returns>
        public List<string> GetAllProceduresYear()
        {
            List<DateTime> procedureyearList = new List<DateTime>();
            List<string> procedureyearListDistinct = new List<string>();


            using (var context = new DataAccessContainer())
            {
                IQueryable<DateTime> procedureyears = from p in context.Procedures
                                                      orderby p.ProcedureStartDateTime ascending
                                                      where p.Archived == false
                                                      select p.ProcedureStartDateTime;
                procedureyearList = procedureyears.ToList();
                int year = 0;
                foreach (DateTime startDate in procedureyearList)
                {
                    if (year != startDate.Year)
                    {
                        year = startDate.Year;
                        procedureyearListDistinct.Add(year.ToString());
                    }
                }

            }
            return procedureyearListDistinct;
        }



