        /// <summary>
        /// Update procedures archived
        ///. Safety classification: No injury or damage to health is possible (IEC 62304 Class A).
        /// </summary>
        public void UpdateProceduresArchived()
        {
            string connectionString = ConfigurationManager.ConnectionStrings["DataAccess"].ConnectionString;
            SqlConnection cnn;
            cnn = new SqlConnection(connectionString);
            SqlCommand cmd = new SqlCommand();
            try
            {
                cmd.CommandText = "Update Procedures set Archived=1";
                cmd.Connection = cnn;
                cnn.Open();
                cmd.ExecuteNonQuery();
                cnn.Close();
            }
            catch
            {
                cnn.Close();
            }

        }

