        /// <summary>
        /// This function adds a Patient in the database
        ///. Safety classification: No injury or damage to health is possible (IEC 62304 Class A).
        /// </summary>
        /// <param name="dateOfBirth">DateTime representing the Patient's birth date.</param>
        /// <param name="firstName">String representing the Patient's first name.</param>
        /// <param name="lastName">String representing the Patient's last name.</param>
        /// <param name="gender">Short representing the Patient's gender.</param>
        /// <param name="physicianID">Integer representing the Patient's physician ID (in the database).</param>
        /// <param name="treatmentDateTime">Datetime representing the treatment date and time.</param>
        /// <param name="hospitalPatientId">String representing the Patient's hospital Id.</param>
        public void AddPatient(DateTime dateOfBirth, string firstName, string lastName, int physicianID, DateTime treatmentDateTime, string hospitalPatientId,
                               double height, double weight, short gender = -1)
        {
            using (var context = new DataAccessContainer())
            {
                Patient newPatient = new Patient();

                newPatient.DateOfBirth = new DateTime(1800, 1, 1);  //dateOfBirth;
                newPatient.FirstName = "Encrypted"; // firstName;
                newPatient.LastName = "Encrypted";  // lastName;
                newPatient.Gender = -1; //gender;
                newPatient.Height = 0; // height;
                newPatient.Weight = 0;  // weight;
                newPatient.PhysicianID = physicianID;
                newPatient.TreatmentDateTime = treatmentDateTime;
                newPatient.HospitalPatientId = hospitalPatientId;
                newPatient.FirstNameEncrypted = EncryptedValue(firstName);
                newPatient.LastNameEncrypted = EncryptedValue(lastName);
                newPatient.DateOfBirthEncrypted = EncryptedValue(dateOfBirth.ToString());
                newPatient.WeightEncrypted = EncryptedValue(weight.ToString());
                newPatient.HeightEncrypted = EncryptedValue(height.ToString());
                newPatient.GenderEncrypted = EncryptedValue(gender.ToString());
                context.Patients.Add(newPatient);
                context.SaveChanges();
            }
        }

        /// <summary>
        /// Function that adds a Physician in the database
        ///. Safety classification: No injury or damage to health is possible (IEC 62304 Class A).
        /// </summary>
        /// <param name="username">The Physician's username.</param>
        public void AddPhysician(string username, int physicianId, string firstname, string lastname, double coolingRequiredTargetTemperature = -30, double thawTimerToTemperature = 0,
            double lowAblationTemperatureAlarm = -45, double highAblationTemperatureAlarm = 30, double esophagusTemperature = 20,
            double diaphragmAmplitude = 80, int diaphragmAmplitudeType = 1, bool balloonPressureSelected = false, bool tipPressureSelected = false,
            int ablationTimer = 240, bool isUsingAutoDeflation = false, short volumeLevel = 50, short curveStyle = 1, short curveColor = 1, string background = "Black",
            int veinIsolationDuration = 60, int requestedAblationTime = 240, double dmsDetectionThreshold = 0.01, short refrigerantLevelUnit = 0, short diaphragmSensorGain = 100,
            bool isUsingInflationFastSpeed = false, bool isUsingAudioAlert = true, int ExpectedVeinIsolationTime = 60, int AblationTimerTTIFixed = 180, int NewAblationTimerTTIFixed = 240,
            int DurationExpectedVeinIsolationTime = 60, int AblationTimerTTI = 180, int NewAblationTimerTTI = 240, Int16 ablationDurationType = 1, bool enabaleEnhancedAudio = true, bool isUsingAutoPlayback = true, 
            int OcclusionPressureGraphSweepSpeed=6, int OcclusionPressureGraphAxisYMaximum=40, int OcclusionPressureGraphAxisYMinimum=10, 
            bool isShowAdvancedView=true, bool isShowPatientInfo=true, bool isUsingShadowing=true)
        {
            using (var context = new DataAccessContainer())
            {
                Physician newPhysician = new Physician();

                preference _preference = new preference();

                _preference.CoolingRequiredTargetTemperature = coolingRequiredTargetTemperature;
                _preference.ThawTimerToTemperature = thawTimerToTemperature;
                _preference.LowAblationTemperatureAlarm = lowAblationTemperatureAlarm;
                _preference.HighAblationTemperatureAlarm = highAblationTemperatureAlarm;
                _preference.EsophagusTemperature = esophagusTemperature;
                _preference.DiaphragmAmplitude = diaphragmAmplitude;
                _preference.DiaphragmAmplitudeType = 1; // diaphragmAmplitudeType;
                _preference.BalloonPressureSelected = balloonPressureSelected;
                _preference.TipPressureSelected = tipPressureSelected;
                _preference.AblationTimer = ablationTimer;
                _preference.IsUsingAutoDeflation = isUsingAutoDeflation;
                _preference.RefrigerantLevelUnit = refrigerantLevelUnit;
                _preference.VolumeLevel = volumeLevel;
                _preference.CurveStyle = curveStyle;
                _preference.CurveColor = curveColor;
                _preference.Background = background;
                _preference.VeinIsolationDuration = veinIsolationDuration;
                _preference.RequestedAblationTime = requestedAblationTime;
                _preference.NewVeinIsolationDuration = 0;
                _preference.NewRequestedAblationTime = 0;
                _preference.DMSDetectionThreshold = dmsDetectionThreshold;
                _preference.DiaphragmSensorGain = diaphragmSensorGain;
                _preference.IsUsingInflationFastSpeed = isUsingInflationFastSpeed;
                _preference.IgnoreDiaphragmMovement = false;
                _preference.OcclusionPressureGraphSweepSpeed = OcclusionPressureGraphSweepSpeed;
                _preference.OcclusionPressureGraphAxisYMinimum = OcclusionPressureGraphAxisYMinimum;
                _preference.OcclusionPressureGraphAxisYMaximum = OcclusionPressureGraphAxisYMaximum;

                //Set Fixed Timer and TTI + TTI Duration default values.
                _preference.ExpectedVeinIsolationTime = ExpectedVeinIsolationTime;
                _preference.AblationTimerTTIFixed = AblationTimerTTIFixed;
                _preference.NewAblationTimerTTIFixed = NewAblationTimerTTIFixed;
                _preference.DurationExpectedVeinIsolationTime = DurationExpectedVeinIsolationTime;
                _preference.AblationTimerTTI = AblationTimerTTI;
                _preference.NewAblationTimerTTI = NewAblationTimerTTI;
                _preference.IsUsingAudioAlert = isUsingAudioAlert;
                _preference.AblationDurationType = ablationDurationType;
                _preference.EnabaleEnhancedAudio = enabaleEnhancedAudio;
                _preference.IsUsingAutoPlayback = isUsingAutoPlayback;

                _preference.IsShowAdvancedView = isShowAdvancedView;
                _preference.IsShowPatientInfo = isShowPatientInfo;
                _preference.IsUsingShadowing = isUsingShadowing;

                newPhysician.ID = physicianId;
                newPhysician.FirstName = "Encrypted FirstName" + physicianId;
                newPhysician.LastName = "Encrypted LastName" + physicianId;
                newPhysician.FirstNameEncrypted = EncryptedValue(firstname);
                newPhysician.LastNameEncrypted = EncryptedValue(lastname);
                newPhysician.Name = username;
                newPhysician.HospitalPhyscianID = "";
                newPhysician.preference = _preference;

                context.Physicians.Add(newPhysician);
                context.SaveChanges();
            }
        }

