        public Physician UpdatePhysician(Physician physician)
        {
            using (var context = new DataAccessContainer())
            {
                string pfirstname = "";
                string plastname = "";
                pfirstname = physician.FirstName;
                plastname = physician.LastName;
                if (physician != null)
                {
                    physician.FirstNameEncrypted = EncryptedValue(pfirstname);
                    physician.LastNameEncrypted = EncryptedValue(plastname);
                    physician.FirstName = "Encrypted";
                    physician.LastName = "Encrypted";
                    //update the current record 
                    context.Entry(physician).State = System.Data.EntityState.Modified;
                    context.Entry(physician.preference).State = System.Data.EntityState.Modified;
                    context.SaveChanges();
                }
                return physician;
            }
        }



