        /// <summary>
        /// Function that gets an Ablation filename in the database
        ///. Safety classification: No injury or damage to health is possible (IEC 62304 Class A).
        /// </summary>
        /// <param name="ablationID">Integer representing an Ablation ID in the database.</param>
        /// <param name="currentHospitalPatientId">String that represents a Patient's Hospital ID in the database.</param>
        /// <param name="procedureID">Integer that represents a Procedure's ID in the database.</param>
        /// <returns>The Ablation filename (string).</returns>
        public string GetAblationFileName(int ablationID, string currentHospitalPatientId, int procedureID)
        {
            int patientID = -1;
            string fileName = "";

            if (ablationID >= 0 && currentHospitalPatientId != "" && procedureID >= 0)
            {
                try
                {
                    patientID = GetPatientID(currentHospitalPatientId);

                    if (patientID >= 0)
                    {
                        using (var context = new DataAccessContainer())
                        {
                            IQueryable<Ablation> ablations = from p in context.Ablations
                                                             where p.AblationNumber == ablationID && p.PatientID == patientID && p.ProcedureId == procedureID
                                                             select p;


                            fileName = ablations.FirstOrDefault()?.DataFile??string.Empty;
                        }
                    }
                }
                catch (Exception exception)
                {
                    throw new Exception("An error occurred while retrieving the ablation file name!", exception);
                }
            }

            return fileName;
        }

