        public void ArchiveProcedures(List<Procedure> lst)
        {
	        if(lst is null) return;

	        using(var dbContext = new DataAccessContainer())
	        {
		        foreach(var p_ in lst)
		        {
			        dbContext.Procedures.Where(x => x.Id == p_.Id).FirstOrDefault().Archived = true;
		        }
		        dbContext.SaveChanges();
	        }
        }

        public void ArchiveProcedure(Procedure procedure)
        {
	        if(procedure == null) return;
	        using(var dbContext = new DataAccessContainer())
	        {
		        dbContext.Procedures.Where(x => x.Id == procedure.Id).FirstOrDefault().Archived = true;
		        dbContext.SaveChanges();
	        }
        }

