        /// <summary>
        /// Function that removes a CatheterInformation from its serial number and lot
        ///. Safety classification: Death or SERIOUS INJURY is possible (IEC 62304 Class C).
        /// </summary>
        /// <id>SF-SDS-0020</id>
        /// <param name="serialNumber">Integer representing a Catheter's serial number.</param>
        /// <param name="lot">Integer representing a Catheter's lot.</param>
        /// <returns>The Catheter's CatheterInformation.</returns>
        public void RemoveCatheterInformationsAccordingToSerialNumberAndLotIfExists(int serialNumber, int lot, int catheterID, bool isUsedForEngineering)
        {
          using (var context = new DataAccessContainer())
          {
            IQueryable<CatheterInformation> catheterInformation = from p in context.CatheterInformations
              where p.SerialNumber == serialNumber && p.Lot == lot &&
                    p.CatheterTypeID == catheterID && p.IsUsedForEngineering == isUsedForEngineering
              select p;
            
            var catheterInfo = catheterInformation.FirstOrDefault();
            if (catheterInfo != null)
            {
              context.CatheterInformations.Attach(catheterInfo);
              context.CatheterInformations.Remove(catheterInfo);
              context.SaveChanges();
            }
          }
        }

