        /// <param name="numberOfInjection">Integer representing a Catheter's number of injections.</param>
        /// <param name="catheterTypeID">Integer representing a Catheter's type ID.</param>
        public void AddCatheterInformation(int serialNumber, int lot, int firmwareVersion, DateTime catheterExpirationDate, DateTime lastUseDate, int numberOfInjection, int catheterTypeID, bool isUsedForEngineering, int overloadedCatheterID)
        {
            using (var context = new DataAccessContainer())
            {
                CatheterInformation newCatheterInformation = new CatheterInformation();

                newCatheterInformation.SerialNumber = serialNumber;
                newCatheterInformation.Lot = lot;
                newCatheterInformation.FirmwareVersion = firmwareVersion;
                newCatheterInformation.CatheterExpirationDate = catheterExpirationDate;
                newCatheterInformation.LastUseDate = lastUseDate;
                newCatheterInformation.NumberOfInjection = numberOfInjection;
                newCatheterInformation.CatheterTypeID = catheterTypeID;
                newCatheterInformation.IsUsedForEngineering = isUsedForEngineering;
                newCatheterInformation.OverloadedCatheterID = overloadedCatheterID;
                context.CatheterInformations.Add(newCatheterInformation);

                context.SaveChanges();
            }
        }

        /// <summary>
        /// Function that inserts a User in the database
        ///. Safety classification: No injury or damage to health is possible (IEC 62304 Class A).
        /// </summary>
        /// <param name="userName">String representing a User's username.</param>
        /// <param name="userPassword">String representing a User's password.</param>
        /// <param name="userType">Integer representing a user's type.</param>
        public int AddNewUser(string userName, string userPassword, int userType, string lastname, string firstname)
        {
            using (var context = new DataAccessContainer())
            {
                User newUser = new User();

                newUser.UserName = userName;
                newUser.Password = userPassword;

                //this part is to handle "not null" 
                //newUser.FirstName = firstname;
                //newUser.LastName = lastname;

                newUser.FirstName = "temp";
                newUser.LastName = "temp";
                newUser.PhoneNumber = "temp";
                newUser.EmailAdredress = "temp";
                newUser.Status = true;

                Type existingtype = context.Types.FirstOrDefault(j => j.Id == userType);

                newUser.Types.Add(existingtype);
                context.Users.Add(newUser);

                try
                {
                    context.SaveChanges();
                }
                catch (Exception ex)
                {
                    ex.ToString();
                }

                // when we create these user we want to know  the foreign key

                return newUser.Id;
            }
        }

