        /// <summary>
        /// Functions that gets if a username already exists in the database.
        ///. Safety classification: No injury or damage to health is possible (IEC 62304 Class A).
        /// </summary>
        /// <param name="user">Current User (if already exists).</param>
        /// <param name="username">String representing the User's username.</param>
        /// <returns>Boolean if the user name already exists or not.</returns>
        public bool DoesUserNameAlreadyExists(User user, string username)
        {
            bool doesUserNameExists = false;

            if (user != null)
            {
                using (var context = new DataAccessContainer())
                {
                    IQueryable<User> users = null;

                    users = from p in context.Users
                            where p.UserName == username &&
                                  p.Id != user.Id
                            select p;

                    doesUserNameExists = users.Any();
                }
            }

            return doesUserNameExists;
        }

