        /// Functions that gets if a physician already exists in the database
        ///. Safety classification: No injury or damage to health is possible (IEC 62304 Class A).
        /// </summary>
        /// <param name="username">String representing the User's username./> </param>
        /// <returns>Boolean if the user name already exists or not.</returns>

        public bool DoesDoctorFullNameAlreadyExists(string firstname, string lastname)
        {
            bool doesDrNameExists = false;
            string DecryptedLastNameValue;
            string DecryptedFirstNameValue;

            using (var context = new DataAccessContainer())
            {
                IQueryable<Physician> physicians = null;

                physicians = from p in context.Physicians
                             select p;

                List<Physician> PList = physicians.ToList();

                foreach (Physician p in PList)
                {
                    DecryptedLastNameValue = DecryptedValue(p.LastNameEncrypted, 1);
                    DecryptedFirstNameValue = DecryptedValue(p.FirstNameEncrypted, 1);
                    if (DecryptedLastNameValue.ToLower() == lastname.ToLower() && DecryptedFirstNameValue.ToLower() == firstname.ToLower())
                    {
                        doesDrNameExists = true;
                        break;
                    }

                }
            }

            return doesDrNameExists;
        }


