        /// <summary>
        /// Function that updates a patient
        ///. Safety classification: No injury or damage to health is possible (IEC 62304 Class A).
        /// </summary>
        /// <param name="patient">Patient to be updated.</param>
        /// <returns>The Patient that has been updated.</returns>
        public Patient UpdatePatient(Patient patient)
        {
            using (var context = new DataAccessContainer())
            {
                if (patient != null)
                {
                    patient.FirstNameEncrypted = EncryptedValue(patient.FirstName);
                    patient.LastNameEncrypted = EncryptedValue(patient.LastName);
                    patient.DateOfBirthEncrypted = EncryptedValue(patient.DateOfBirth.ToString());
                    patient.WeightEncrypted = EncryptedValue(patient.Weight.ToString());
                    patient.HeightEncrypted = EncryptedValue(patient.Height.ToString());
                    patient.GenderEncrypted = EncryptedValue(patient.Gender.ToString());

                    patient.DateOfBirth = new DateTime(1800, 1, 1);  //dateOfBirth;
                    patient.FirstName = "Encrypted"; // firstName;
                    patient.LastName = "Encrypted";  // lastName;
                    patient.Gender = -1; //gender;
                    patient.Height = 0; // height;
                    patient.Weight = 0;  // weight;

                    context.Entry(patient).State = System.Data.EntityState.Modified;
                    context.SaveChanges();
                }
                return patient;
            }
        }

