        /// <summary>
        /// Update the user information
        ///. Safety classification: No injury or damage to health is possible (IEC 62304 Class A).
        /// </summary>
        /// <param name="user">the user to update </param>
        /// <param name="userType">the user type</param>
        /// <returns></returns>
        public User UpdateUser(User user, int userType)
        {
            using (var context = new DataAccessContainer())
            {
                if (user != null)
                {
                    var users = context.Users.Include("Types")
                                    .Single(u => u.Id == user.Id);

                    users.Types.Clear();

                    Type existingtype = context.Types.FirstOrDefault(j => j.Id == userType);

                    users.Types.Add(existingtype);

                    if (!string.IsNullOrWhiteSpace(user.UserName))
                    {
                        users.UserName = user.UserName;
                        users.FirstName = "temp";
                        users.LastName = "temp";
                    }

                    context.SaveChanges();
                }
                return user;
            }
        }

        /// <summary>
        /// This function deletes a User.  It actually set its status to False, no data is deleted since 
        /// we want to keep the historic (actions, ablations, etc) of each Users.
        ///. Safety classification: No injury or damage to health is possible (IEC 62304 Class A).
        /// </summary>
        /// <param name="user">The user to be deleted.</param>
        /// <returns>The deleted User.</returns>
        public User DeleteUser(User user)
        {
            using (var context = new DataAccessContainer())
            {
                if (user != null)
                {
                    //Do not delete the record, set it to inactive.
                    user.Status = false;
                    context.Entry(user).State = System.Data.EntityState.Modified;
                    context.SaveChanges();
                }
                return user;
            }
        }

