                    cMCRegisterValues.FirstOrDefault().PGain = pgain;
                    cMCRegisterValues.FirstOrDefault().IGain = igain;
                    cMCRegisterValues.FirstOrDefault().DGain = dgain;
                    cMCRegisterValues.FirstOrDefault().Offset = offset;

                    context.SaveChanges();
                }
            }
        }

