        /// <summary>
        /// This function verifies if the combination of username / password exists in the database and 
        /// return the corresponding active User.
        ///. Safety classification: No injury or damage to health is possible (IEC 62304 Class A).
        /// </summary>
        /// <param name="username">String representing the User's username.</param>
        /// <param name="password">String representing the User's password.</param>
        /// <returns>The User corresponding to the username and password (if any).</returns>
        public User ConnectUser(string username, string password)
        {
            User user = null;

            if (!string.IsNullOrWhiteSpace(username) && !string.IsNullOrWhiteSpace(password))
            {
                using (var context = new DataAccessContainer())
                {
                    IQueryable<User> users = null;

                    users = from p in context.Users.Include("Types")
                            where p.UserName == username &&
                                  p.Password != "" &&
                                  p.Status == true              //Only active users can log-in
                            select p;

                    foreach (User _user in users)
                    {
                        if (AncestralPasswordEncrypter.DecryptPassword(_user.Password) == password)
                        {
                            user = _user;
                            break;
                        }
                    }

                    //user = users.FirstOrDefault();

                }
            }
            return user;
        }

