        /// <summary>
        /// Add controller PID log
        ///. Safety classification: No injury or damage to health is possible (IEC 62304 Class A).
        /// </summary>
        /// <param name="FM1">FM1</param>
        /// <param name="PT2">PT2</param>
        /// <param name="TargetFlow">Target flow</param>
        /// <param name="TargetInjectionPressure">Target injection pressure</param>
        /// <param name="TargetFlowError"></param>
        /// <param name="TargetInjectionPressureError">Target injection pressure error</param>
        /// <param name="P">PID proportional gain</param>
        /// <param name="I">PID integral gain</param>
        /// <param name="D">PID derivative gain</param>
        /// <param name="O">PID offset</param>
        public void AddCMCUPIDLoga(double FM1, double PT2, double TargetFlow, double TargetInjectionPressure, double TargetFlowError, double TargetInjectionPressureError,
          double P, double I, double D, double O)
        {
            using (var context = new DataAccessContainer())
            {

                CMCUPIDLogs cMCUPIDLogs = new CMCUPIDLogs();

                cMCUPIDLogs.FM1 = FM1;
                cMCUPIDLogs.PT2 = PT2;
                cMCUPIDLogs.TargetFlow = TargetFlow;
                cMCUPIDLogs.TargetInjectionPressure = TargetInjectionPressure;
                cMCUPIDLogs.TargetFlowError = TargetFlowError;
                cMCUPIDLogs.TargetInjectionPressureError = TargetInjectionPressureError;
                cMCUPIDLogs.P = P;
                cMCUPIDLogs.I = I;
                cMCUPIDLogs.D = D;
                cMCUPIDLogs.O = O;
                cMCUPIDLogs.DateOfChange = DateTime.Now;


                context.CMCUPIDLogs.Add(cMCUPIDLogs);
                context.SaveChanges();
            }
        }

