        /// <summary>
        /// Add patient PID log
        ///. Safety classification: No injury or damage to health is possible (IEC 62304 Class A).
        /// </summary>
        /// <param name="PT3">PT3</param>
        /// <param name="IBP">Inner balloon pressure</param>
        /// <param name="OBP">Outer balloon pressure</param>
        /// <param name="PWMINJ">Pulse Width Modulation for the injection</param>
        /// <param name="PWMBAL">Pulse Width Modulation for the ballon</param>
        /// <param name="TargetBalloonPressure">Target balloon pressure</param>
        /// <param name="TargetBallonPressureError">Target ballon pressure error</param>
        /// <param name="P">PID proportional gain</param>
        /// <param name="I">PID integral gain</param>
        /// <param name="D">PID derivative gain</param>
        /// <param name="O">PID offset</param>
        public void AddPMCUPIDLoga(double PT3, double IBP, double OBP, double PWMINJ, double PWMBAL, double TargetBalloonPressure,
            double TargetBallonPressureError, double P, double I, double D, double O)
        {
            using (var context = new DataAccessContainer())
            {

                PMCUPIDLogs pMCUPIDLogs = new PMCUPIDLogs();

                pMCUPIDLogs.PT3 = PT3;
                pMCUPIDLogs.IBP = IBP;
                pMCUPIDLogs.OBP = OBP;
                pMCUPIDLogs.PWMINJ = PWMINJ;
                pMCUPIDLogs.PWMBAL = PWMBAL;
                pMCUPIDLogs.TargetBalloonPressure = TargetBalloonPressure;
                pMCUPIDLogs.TargetBallonPressureError = TargetBallonPressureError;
                pMCUPIDLogs.P = P;
                pMCUPIDLogs.I = I;
                pMCUPIDLogs.D = D;
                pMCUPIDLogs.O = O;
                pMCUPIDLogs.DateOfChange = DateTime.Now;


                context.PMCUPIDLogs.Add(pMCUPIDLogs);
                context.SaveChanges();
            }
        }


