        /// <summary> 
        /// Get field translation by field and current language
        ///. Safety classification: No injury or damage to health is possible (IEC 62304 Class A).
        /// </summary>
        /// <param name="field">Field to translate</param>
        /// <param name="currentLanguage">Current language</param>
        /// <returns>The translation of field to current language</returns>
        public string TranslateField(string field, int currentLanguage)
        {

            using (var context = new DataAccessContainer())
            {
                try
                {
                    IQueryable<GUIField> guiFields = null;

                    guiFields = from p in context.GUIFields.Include("Translations")
                                where p.Text == field && p.Translations.FirstOrDefault().GUIFieldId == p.Id && p.Translations.FirstOrDefault().LanguageId == currentLanguage
                                select p;


                    return guiFields.FirstOrDefault().Translations.FirstOrDefault().FieldTranslation;
                }

                catch (Exception ex)
                {
                    ex.ToString();
                    return "No Translation";
                }

            }

        }


