        /// <summary> 
        /// Get all translations for Current language
        ///. Safety classification: No injury or damage to health is possible (IEC 62304 Class A).
        /// </summary>
        /// <returns>Dictionary for Current language</returns>
        public Dictionary<string, string> GetAllTranslationsForCurrentLanguage()
        {
            int currentLanguage = GetCurrentLanguageId();
            Dictionary<string, string> languageDictionary = new Dictionary<string, string>();

            using (var context = new DataAccessContainer())
            {
                IQueryable<GUIField> guiFields = null;

                guiFields = from p in context.GUIFields.Include("Translations")
                            select p;

                foreach (GUIField _gUIField in guiFields)
                {
                    var translation = _gUIField.Translations.Where(x => x.LanguageId == currentLanguage);
                    if (translation != null)
                    {
                        if (translation.FirstOrDefault() != null)
                            languageDictionary.Add(_gUIField.Text, translation.FirstOrDefault().FieldTranslation);
                        else
                        {
                            languageDictionary.Add(_gUIField.Text, _gUIField.Text);
                        }
                    }
                }
                return languageDictionary;

            }

        }


        /// <summary> 
        /// Get all errors translations for current language
        ///. Safety classification: No injury or damage to health is possible (IEC 62304 Class A).
        /// </summary>
        /// <returns>Dictionary of all errors translations for current language</returns>
        public Dictionary<long, string> GetAllErrorsTranslationsForCurrentLanguage()
        {
            int currentLanguage = GetCurrentLanguageId();
            Dictionary<long, string> languageDictionary = new Dictionary<long, string>();

            using (var context = new DataAccessContainer())
            {
                IQueryable<Error> errors = null;

                errors = from p in context.Errors.Include("ErrorMessages")
                         select p;

                foreach (Error _errors in errors)
                {
                    var translation = _errors?.ErrorMessages.Where(x => x.LanguageId == currentLanguage);

                    if (translation != null)
                    {
                        languageDictionary.Add(_errors.Code, translation?.FirstOrDefault()?.Message);
                    }
                }


                return languageDictionary;

            }

        }


        /// <summary> 
        /// Get all errors and solution translations for current language
        ///. Safety classification: No injury or damage to health is possible (IEC 62304 Class A).
        /// </summary>
        /// <returns>List of Tuples  of all errors, solution and  translations for current language</returns>
        public List<Tuple<long, string, string>> GetAllErrorsAndSolutionTranslationsForCurrentLanguage()
        {
            int currentLanguage = GetCurrentLanguageId();
            List<Tuple<long, string, string>> languageTuple = new List<Tuple<long, string, string>>();

            using (var context = new DataAccessContainer())
            {
                IQueryable<Error> errors = null;

                errors = from p in context.Errors.Include("ErrorMessages")
                         select p;

                foreach (Error _errors in errors)
                {
                    var translation = _errors?.ErrorMessages.Where(x => x.LanguageId == currentLanguage);

                    if (translation != null)
                    {
                        languageTuple.Add(Tuple.Create(_errors.Code, translation?.FirstOrDefault()?.Message, translation?.FirstOrDefault()?.SolutionMessage));
                    }
                }


                return languageTuple;

            }

        }

        /// <summary> 
        /// Get error and solution translations for current language by error id and error type
        ///. Safety classification: No injury or damage to health is possible (IEC 62304 Class A).
        /// </summary>
        /// <param name="errorId">The error ID</param>
        /// <param name="errorType">The error type</param>
        /// <returns>The solution the current language</returns>
        public Tuple<long, string, string, string> GetErrorAndSolutionTranslationsForCurrentLanguage(int errorId, int errorType)
        {
          var errors = _errorMessagesCache.Where(e => e.ErrorCode == errorId && e.Type == errorType);

          if (!errors.Any())
          {
            using (var context = new DataAccessContainer())
            {
              errors = (from p in context.ErrorMessages
                        where p.ErrorCode == errorId && p.Type == errorType && p.LanguageId == 1
                        select p).ToList();

              lock (_errorMessagesCache)
              {
                _errorMessagesCache.AddRange(errors);
              }
            }
          }

          var errorMessage = errors.FirstOrDefault();
          return Tuple.Create(errorMessage.ErrorCode, errorMessage.Message, errorMessage.SolutionMessage, errorMessage.CryterionMessage);
        }

        /// <summary> 
        /// Get error and solution translations for current language by error id and error type
        ///. Safety classification: No injury or damage to health is possible (IEC 62304 Class A).
        /// </summary>
        /// <param name="errorId">The error ID</param>
        /// <param name="errorType">The error type</param>
        /// <returns>The solution the current language</returns>
        public Tuple<long, string, string, string, int> GetErrorMessageWithErrorTypeById(int errorId, int errorType)
        {
            var errorMessage = GetErrorAndSolutionTranslationsForCurrentLanguage(errorId, errorType);
            return Tuple.Create(errorMessage.Item1, errorMessage.Item2, errorMessage.Item3, errorMessage.Item4, errorType);
        }

        /// <summary> 
        /// Update flow curve parameters
        ///. Safety classification: Death or SERIOUS INJURY is possible (IEC 62304 Class C). 
        /// </summary>
        /// <id>SF-SDS-0016</id>
        /// <param name="state">system state</param>
        /// <param name="fm1LowOffset"> FM one low offset</param>
        /// <param name="thFM1High">FM one threshold high limit</param>
        /// <param name="fm1LowFit">FM one low fit</param>
        /// <param name="fm1LowCeiling">FM one low ceiling </param>
        /// <param name="catheterTypeID">Catheter type</param>
        public void UpdateFlowCurveParameters(int state, double fm1LowOffset, double thFM1High, double fm1LowFit, double fm1LowCeiling, int catheterTypeID)
        {
            using (var context = new DataAccessContainer())
            {
                IQueryable<CMCRegisterValue> cMCRegisterValues = from p in context.CMCRegisterValues
                                                                 where p.CatheterTypeID == catheterTypeID && p.StateID == state
                                                                 select p;
                if (cMCRegisterValues.Any())
                {
                    cMCRegisterValues.FirstOrDefault().FM1FlowMeterThresholLowlimit = fm1LowOffset;
                    cMCRegisterValues.FirstOrDefault().FM1FlowMeterThresholHighlimit = thFM1High;
                    cMCRegisterValues.FirstOrDefault().FM1FlowMeterLowRangeLimit = fm1LowFit;
                    cMCRegisterValues.FirstOrDefault().FM1FlowMeterHighRangelimit = fm1LowCeiling;



                    context.SaveChanges();
                }
            }
        }



