        /// <returns>Dictionary of catheters desctiption</returns>
        public Dictionary<int, string> GetCathetersDesctiption()
        {

            Dictionary<int, string> cathetersDesctiptionDictionary = new Dictionary<int, string>();

            using (var context = new DataAccessContainer())
            {
                IQueryable<CatheterType> catheterTypes = null;

                catheterTypes = from p in context.CatheterTypes
                                select p;

                foreach (CatheterType _catheterTypes in catheterTypes)
                {


                    if (_catheterTypes != null)
