        /// <summary>
        /// Update balloon parameters values
        /// . Safety classification: Death or SERIOUS INJURY is possible (IEC 62304 Class C).
        /// </summary>
        /// <id>SF-SDS-0012</id>
        /// <param name="state">System state</param>
        /// <param name="rampUpTimeByStep">Ramp up time by step</param>
        /// <param name="pressureRampUpValue">Pressure ramp up value</param>
        /// <param name="rampDownTimeByStep">Ramp down time by step</param>
        /// <param name="pressureRampDownValue">Pressure ramp down value</param>
        public void UpdateBalloonParametersValues(int state, double rampUpTimeByStep, double pressureRampUpValue, double rampDownTimeByStep, double pressureRampDownValue)
        {
            using (var context = new DataAccessContainer())
            {

                IQueryable<BalloonParameters> balloonParameters = from p in context.BalloonParameters
                                                                  where p.StateID == state
                                                                  select p;
                if (balloonParameters.Any())
                {
                    balloonParameters.FirstOrDefault().RampUpTimeByStep = rampUpTimeByStep;
                    balloonParameters.FirstOrDefault().PressureRampUpValue = pressureRampUpValue;
                    balloonParameters.FirstOrDefault().RampDownTimeByStep = rampDownTimeByStep;
                    balloonParameters.FirstOrDefault().PressureRampDownValue = pressureRampDownValue;

                    context.SaveChanges();
                }
            }
        }

