        /// <summary>
        /// Add new Version
        ///. Safety classification: No injury or damage to health is possible (IEC 62304 Class A).
        /// </summary>
        public void AddErrorLog(string ErrorInformation, DateTime ErrorDate, long ErrorCode, int ErrorType, int VersionId, int? CatheterID, int SystemStatesID, int? UserID, bool IsUsingICB, bool IsUsingRemote, string catheterContainer)
        {
            using (var context = new DataAccessContainer())
            {
                ErrorLog newErrorLog = new ErrorLog();

                newErrorLog.ErrorInformation = ErrorInformation;
                newErrorLog.ErrorDate = ErrorDate;
                newErrorLog.ErrorCode = ErrorCode;
                newErrorLog.ErrorType = ErrorType;
                newErrorLog.VersionId = VersionId;
                newErrorLog.CatheterID = CatheterID;
                newErrorLog.SystemStatesID = SystemStatesID;
                newErrorLog.UserID = UserID;
                newErrorLog.IsUsingICB = IsUsingICB;
                newErrorLog.IsUsingRemote = IsUsingRemote;
                newErrorLog.CatheterContainer = catheterContainer; 

                context.ErrorLogs.Add(newErrorLog);
                context.SaveChanges();
            }
        }



